ValidationRule.errorConditionFormula:
AND(
   /* Applies to Account Support case record type only*/
   RecordTypeId = '0121a000000AXYM',
   ISPICKVAL( Status , "Closed"),
   ISCHANGED(Status),
   OR(
      /* Id of 'Core User' */ 
      OwnerId = '0054z000009jrjj',
      /* Id of 'Core Support' user*/
      OwnerId = '0054z00000CXHhQ',
      /* Id of 'AGP User' user*/
      OwnerId = '0054z000009jrBh',
      /* Id of 'Salesforce Data Cycle' user*/
      OwnerId = '0051a000002i3pE',
      /* User Ids always start with '005', queues start with '00G' */
      NOT(BEGINS(OwnerId, '005'))
    ),
    /* Flow will change checkbox if it needs to bypass this rule*/
    NOT(ISCHANGED(BypassCaseValidation__c ))
)
